    IF EXISTS (SELECT 1 FROM pg_partitioned_table WHERE partrelid = to_regclass('ai_work_program_version')) THEN
        CREATE TABLE IF NOT EXISTS "ai_work_program_version_p06" PARTITION OF "ai_work_program_version" FOR VALUES WITH (MODULUS 16, REMAINDER 6);
